<?php if ($documents === []): ?><p class="empty"><?= e(__('empty.documents')) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(__('fields.document')) ?></th><th><?= e(__('fields.case')) ?></th><th></th></tr></thead><tbody><?php foreach ($documents as $doc): ?><tr><td><?= e($doc['original_name']) ?></td><td><?= e($doc['case_number']) ?></td><td><a href="<?= e(url('/portal/documents/' . $doc['id'] . '/download')) ?>"><?= e(__('actions.download')) ?></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
